/* Test vectors generated by running T3 Code (MIT) packages/shared/src/composerContextReferences.ts (upstream 7deb51b550):
 * toKindScopedComposerContextId, sanitizeComposerContextLabel, formatComposerContextReference, threadContextRecord and
