package com.tajchert.trefoil.core.model

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Test

class ThreadReferencesTest {
    private val uuid = "0b5f2c1e-8a4d-4c7a-9e3b-1f6d2a7c9b10"
    private val prefix = "t3-context://v1/thread/"

    private fun thread(id: String, title: String = "Title $id", deletedAt: String? = null) =
        ThreadSummary(id = id, projectId = "p", title = title, deletedAt = deletedAt)

    private fun ctx(id: String) = toComposerContextId("thread", id)

    // contextId, label, start, end of the references in [text].
    private fun found(text: String) = collectThreadReferenceMatches(text).map { listOf(it.reference.contextId, it.reference.label, it.start, it.end) }

    // --- toComposerContextId -------------------------------------------------------------------------------------------

    @Test fun uuidThreadIdKeepsThePlainPrefixedForm() {
        assertEquals("thread_$uuid", ctx(uuid))
    }

    @Test fun mixedCaseIdMatchingThePatternIsKept() {
        assertEquals("thread_Thread_ABC-123", ctx("Thread_ABC-123"))
    }

    @Test fun nonMatchingIdBecomesSlugAndDigest() {
        assertEquals("thread_thread-one-e12fece08fd88673", ctx("thread:one"))
        assertEquals("thread_a-b-c-41f2b821c7c11db4", ctx("a/b c"))
    }

    @Test fun trailingNewlineDoesNotMatchThePattern() {
        assertEquals("thread_abc-8a6b4a7ca5c1d50f", ctx("abc\n"))
    }

    @Test fun nonAsciiIdsLeaveOnlyTheEdgeTrimmedSlug() {
        assertEquals("thread_-f654d0e37de62788", ctx("日本語-スレッド"))
        // Surrogate pairs hash as two UTF-16 code units.
        assertEquals("thread_-x-3299606e8247bb81", ctx("😀😀x"))
    }

    @Test fun emptyIdStillMatchesThePattern() {
        assertEquals("thread_", ctx(""))
    }

    @Test fun lengthLimitIs128IncludingThePrefix() {
        assertEquals("thread_" + "b".repeat(121), ctx("b".repeat(121)))
        assertEquals("thread_" + "b".repeat(41) + "-41456e3e1d4bad2d", ctx("b".repeat(122)))
        assertEquals("thread_" + "a".repeat(41) + "-efd35010639514e3", ctx("a".repeat(130)))
    }

    @Test fun slugIsCutAt48CharsBeforeTheDigest() {
        val id = "x".repeat(60) + " " + "y".repeat(60)
        assertEquals("thread_" + "x".repeat(41) + "-201584d27380b3a5", ctx(id))
    }

    @Test fun otherKindsUseTheirOwnPrefix() {
        assertEquals("terminal_abc", toComposerContextId("terminal", "abc"))
    }

    // --- sanitizeContextLabel ------------------------------------------------------------------------------------------

    @Test fun bracketsBackslashAndLineBreaksBecomeOneSpace() {
        assertEquals("a b c d e", sanitizeContextLabel("a[b]c\\d\r\ne"))
        assertEquals("a b c", sanitizeContextLabel("  a   b\t\tc  "))
    }

    @Test fun longTitleIsCutAt200() {
        assertEquals("x".repeat(200), sanitizeContextLabel("x".repeat(300)))
        assertEquals("z".repeat(200), sanitizeContextLabel("z".repeat(200)))
    }

    @Test fun surrogatePairStraddlingTheLimitIsNotSplit() {
        val straddling = sanitizeContextLabel("a".repeat(199) + "😀" + "tail")
        assertEquals("a".repeat(199), straddling)
        val fitting = sanitizeContextLabel("a".repeat(198) + "😀" + "tail")
        assertEquals("a".repeat(198) + "😀", fitting)
        assertEquals(200, fitting.length)
    }

    @Test fun loneHighSurrogateAtTheLimitIsKept() {
        val label = sanitizeContextLabel("a".repeat(199) + "\ud83d" + "b")
        assertEquals("a".repeat(199) + "\ud83d", label)
    }

    @Test fun blankTitleFallsBackToThread() {
        assertEquals("thread", sanitizeContextLabel(" \t\r\n "))
        assertEquals("thread", sanitizeContextLabel(""))
        assertEquals("thread", sanitizeContextLabel("[]"))
    }

    @Test fun whitespaceFollowsTheJavaScriptSet() {
        assertEquals("hello world", sanitizeContextLabel("  hello　 world﻿ "))
        // NEL (U+0085) and U+001C are not JavaScript whitespace, and neither is U+180E.
        assertEquals("\u0085x\u001cy", sanitizeContextLabel("\u0085x\u001cy"))
        assertEquals("x y z w v ᠎", sanitizeContextLabel("x\u000by\u000cz w v   ᠎"))
    }

    // --- markers -------------------------------------------------------------------------------------------------------

    @Test fun markerUsesTheSanitizedTitleAndContextId() {
        assertEquals("[Fix the bug]($prefix" + "thread_$uuid)", threadReferenceMarker(uuid, "Fix [the] bug\n"))
        assertEquals("[thread]($prefix" + "thread_thread-one-e12fece08fd88673)", threadReferenceMarker("thread:one", ""))
    }

    @Test fun markerRoundTripsThroughCollect() {
        val text = "see " + threadReferenceMarker(uuid, "Fix [the] bug") + " please"
        assertEquals(listOf(ThreadReference("Fix the bug", "thread_$uuid")), collectThreadReferences(text))
        assertEquals("[Fix the bug]($prefix" + "thread_$uuid)", collectThreadReferences(text).single().marker())
    }

    // --- parsing --------------------------------------------------------------------------------------------------------

    @Test fun collectKeepsThreadReferencesWithPositions() {
        val text = "see [A](${prefix}thread_abc) and ![img](t3-context://v1/image/img_1) end [B b]($prefix" + "thread_abc)"
        assertEquals(
            listOf(listOf("thread_abc", "A", 4, 42), listOf("thread_abc", "B b", 87, 127)),
            found(text),
        )
    }

    @Test fun collectAcceptsAdjacentMarkersAndImagePrefixedThreads() {
        assertEquals(
            listOf(listOf("x", "a", 0, 29), listOf("y", "b", 29, 58)),
            found("[a](${prefix}x)[b](${prefix}y)"),
        )
        assertEquals(listOf(listOf("x", "a", 0, 30)), found("![a](${prefix}x)"))
    }

    @Test fun collectSanitizesTheLabelOfAMarkerAndFallsBackToThread() {
        assertEquals(listOf(listOf("x", "a b", 0, 35)), found("[ a   b ](${prefix}x)"))
        assertEquals(listOf(listOf("x", "thread", 0, 28)), found("[](${prefix}x)"))
        assertEquals(listOf(listOf("x", "a(b)", 0, 32)), found("[a(b)](${prefix}x)"))
    }

    @Test fun collectKeepsMixedCaseIds() {
        assertEquals(listOf(listOf("ABC_def-9", "a", 0, 37)), found("[a](${prefix}ABC_def-9)"))
    }

    @Test fun collectEnforcesTheLabelBoundInUtf16Units() {
        assertEquals(1, found("[" + "q".repeat(512) + "](${prefix}x)").size)
        assertEquals(emptyList<Any>(), found("[" + "q".repeat(513) + "](${prefix}x)"))
        // 257 emoji are 514 UTF-16 units: too long, although only 257 code points.
        assertEquals(emptyList<Any>(), found("[" + "😀".repeat(257) + "](${prefix}x)"))
        assertEquals(emptyList<Any>(), found("[a\nb](${prefix}x)"))
    }

    @Test fun collectRejectsInvalidHrefs() {
        assertEquals(emptyList<Any>(), found("[a](t3-context://v1/Thread/x)"))
        assertEquals(emptyList<Any>(), found("[a](t3-context://v1/thread/a/b)"))
        assertEquals(emptyList<Any>(), found("[a](t3-context://v1/thread/a b)"))
        assertEquals(emptyList<Any>(), found("[a](t3-context://v2/thread/x)"))
        assertEquals(emptyList<Any>(), found("[a](T3-context://v1/thread/x)"))
        assertEquals(emptyList<Any>(), found("[a](${prefix}x\n)"))
        assertEquals(emptyList<Any>(), found("[a](${prefix}${"i".repeat(129)})"))
        assertEquals(emptyList<Any>(), found("[a](${prefix}${"i".repeat(173)})"))
        assertEquals(emptyList<Any>(), found("[a](${prefix}${"i".repeat(174)})"))
        assertEquals(emptyList<Any>(), found("[a](t3-context://v1/1k/x)"))
        assertEquals(emptyList<Any>(), found("[a](t3-context://v1/${"k".repeat(41)}/x)"))
    }

    @Test fun collectIgnoresOtherKinds() {
        assertEquals(emptyList<Any>(), found("[a](t3-context://v1/${"k".repeat(40)}/x)"))
        assertEquals(emptyList<Any>(), found("![img](t3-context://v1/image/img_1)"))
    }

    @Test fun collectScansOnAfterAFailedAttemptButNotAfterAnInvalidMatch() {
        // The first href is over 200 units, so it never matched; the marker inside it does.
        assertEquals(listOf(listOf("ok", "x", 217, 247)), found("[a](${prefix}${"i".repeat(190)}[x](${prefix}ok)"))
        assertEquals(listOf(listOf("ok", "x", 197, 227)), found("[a](${prefix}${"i".repeat(170)}[x](${prefix}ok)"))
        assertEquals(listOf(listOf("x", "a", 3, 32)), found("[x [a](${prefix}x)"))
    }

    @Test fun collectOnPlainTextIsEmpty() {
        assertEquals(emptyList<Any>(), found("no markers [here](https://example.com)"))
        assertEquals(emptyList<Any>(), found(""))
    }

    // --- context records ------------------------------------------------------------------------------------------------

    @Test fun recordMatchesTheUpstreamRecordExactly() {
        val text = threadReferenceMarker("thread:one", "Fix [the] bug")
        val records = threadContextRecords(text, listOf(thread("thread:one", "Fix [the] bug")), "env-1")
        assertNotNull(records)
        assertEquals(
            """{"version":1,"kind":"thread","contextId":"thread_thread-one-e12fece08fd88673","label":"Fix the bug","environmentId":"env-1","threadId":"thread:one","title":"Fix the bug"}""",
            records!!.single().toString(),
        )
    }

    @Test fun markerAndRecordShareTheContextId() {
        val text = "look at ${threadReferenceMarker(uuid, "Plan")}"
        val record = threadContextRecords(text, listOf(thread(uuid, "Plan")), "env")!!.single() as JsonObject
        assertEquals(collectThreadReferences(text).single().contextId, record["contextId"]!!.jsonPrimitive.content)
        assertEquals(uuid, record["threadId"]!!.jsonPrimitive.content)
    }

    @Test fun recordTitleIsTheThreadsCurrentTitleNotTheMarkerLabel() {
        val text = "[Old name]($prefix" + "thread_t1)"
        val record = threadContextRecords(text, listOf(thread("t1", "New [name]")), "env")!!.single() as JsonObject
        assertEquals("New name", record["label"]!!.jsonPrimitive.content)
        assertEquals("New name", record["title"]!!.jsonPrimitive.content)
    }

    @Test fun recordTitleIsSanitizedAndCapped() {
        val text = threadReferenceMarker("t1", "x")
        val record = threadContextRecords(text, listOf(thread("t1", "y".repeat(300))), "env")!!.single() as JsonObject
        assertEquals("y".repeat(200), record["title"]!!.jsonPrimitive.content)
    }

    @Test fun unknownThreadYieldsNoRecord() {
        val text = threadReferenceMarker("ghost", "Ghost")
        assertNull(threadContextRecords(text, listOf(thread("other")), "env"))
        assertNull(threadContextRecords(text, emptyList(), "env"))
    }

    @Test fun deletedThreadYieldsNoRecord() {
        val text = threadReferenceMarker("t1", "T")
        assertNull(threadContextRecords(text, listOf(thread("t1", deletedAt = "2026-01-01T00:00:00Z")), "env"))
    }

    @Test fun onlyKnownReferencesGetRecordsInOrderOfFirstAppearance() {
        val text = listOf("b", "ghost", "a", "b").joinToString(" ") { threadReferenceMarker(it, "T $it") }
        val records = threadContextRecords(text, listOf(thread("a"), thread("b"), thread("c")), "env")!!
        assertEquals(listOf("b", "a"), records.map { (it as JsonObject)["threadId"]!!.jsonPrimitive.content })
    }

    @Test fun repeatedReferenceIsDeduplicatedByContextId() {
        val marker = threadReferenceMarker("a", "A")
        val records = threadContextRecords("$marker and again $marker", listOf(thread("a")), "env")!!
        assertEquals(1, records.size)
    }

    @Test fun recordsAreCappedAt200() {
        val threads = (1..201).map { thread("t$it") }
        val text = threads.joinToString(" ") { threadReferenceMarker(it.id, it.title) }
        val records = threadContextRecords(text, threads, "env")!!
        assertEquals(200, records.size)
        assertEquals("t1", (records.first() as JsonObject)["threadId"]!!.jsonPrimitive.content)
        assertEquals("t200", (records.last() as JsonObject)["threadId"]!!.jsonPrimitive.content)
    }

    @Test fun noMarkersYieldNull() {
        assertNull(threadContextRecords("plain text", listOf(thread("a")), "env"))
        assertNull(threadContextRecords("![img](t3-context://v1/image/a)", listOf(thread("a")), "env"))
    }

    @Test fun threadWithANonMatchingIdIsPairedThroughTheDigestForm() {
        val text = threadReferenceMarker("日本語-スレッド", "JP")
        val record = threadContextRecords(text, listOf(thread("日本語-スレッド", "JP")), "env")!!.single() as JsonObject
        assertEquals("thread_-f654d0e37de62788", record["contextId"]!!.jsonPrimitive.content)
        assertEquals("日本語-スレッド", record["threadId"]!!.jsonPrimitive.content)
    }

    // --- draft splitting ------------------------------------------------------------------------------------------------

    private fun ref(id: String, label: String = "T $id") = ThreadReference(label, ctx(id))

    @Test fun splitWithoutReferencesIsTheBody() {
        val draft = splitThreadReferenceDraft("just words")
        assertEquals(ThreadReferenceDraft("just words", emptyList()), draft)
        assertEquals("just words", draft.text())
    }

    @Test fun splitTakesLeadingMarkersAndTheirBlankLineOffTheBody() {
        val text = "${ref("a").marker()}\n${ref("b").marker()}\n\nwhat do you think?"
        val draft = splitThreadReferenceDraft(text)
        assertEquals(listOf(ref("a"), ref("b")), draft.references)
        assertEquals("what do you think?", draft.body)
        assertEquals(text, draft.text())
    }

    @Test fun splitOfOnlyMarkersHasAnEmptyBody() {
        val text = "${ref("a").marker()}\n${ref("b").marker()}"
        val draft = splitThreadReferenceDraft(text)
        assertEquals("", draft.body)
        assertEquals(listOf(ref("a"), ref("b")), draft.references)
        assertEquals(text, draft.text())
    }

    @Test fun splitLiftsAPastedMarkerOutOfTheBody() {
        val draft = splitThreadReferenceDraft("compare with ${ref("a").marker()} please")
        assertEquals("compare with  please", draft.body)
        assertEquals(listOf(ref("a")), draft.references)
        assertEquals("${ref("a").marker()}\n\ncompare with  please", draft.text())
    }

    @Test fun splitHandlesLeadingAndPastedMarkersTogether() {
        val draft = splitThreadReferenceDraft("${ref("a").marker()}\n\nsee ${ref("b").marker()} too")
        assertEquals(listOf(ref("a"), ref("b")), draft.references)
        assertEquals("see  too", draft.body)
    }

    @Test fun joinPutsMarkersOneToALineThenABlankLine() {
        assertEquals("body", joinThreadReferenceDraft("body", emptyList()))
        assertEquals(ref("a").marker(), joinThreadReferenceDraft("", listOf(ref("a"))))
        assertEquals("${ref("a").marker()}\n${ref("b").marker()}\n\nbody", joinThreadReferenceDraft("body", listOf(ref("a"), ref("b"))))
    }

    @Test fun splitIgnoresCitationAndOtherContextMarkers() {
        val text = "[x](t3-context://v1/image/img_1) hello"
        assertEquals(ThreadReferenceDraft(text, emptyList()), splitThreadReferenceDraft(text))
    }
}
